[TFMListElementAttribute('imageElement')]
class TFMListImageElement extends TFMListElement
{
    TFMListWidth width;
    TFMListHeight height;
    TFMDataSetField sourceId;
    TFMDataSetField dataMember;
    Map				dataMemberValues;
    TFMListValuesElement valuesElement;

}

