public TFMListValueElement addValueElement(Description255 _dataMemberValue, ResourceName _ImageId)
{
    if(!valuesElement)
    {
        MapEnumerator mEnum = this.getChildren().getEnumerator();
        while(mEnum.moveNext())
        {
            if(mEnum.currentValue() as TFMListValuesElement)
            {
                valuesElement = mEnum.currentValue();
            }
        }
        if(!valuesElement)
        {
            valuesElement = new TFMListValuesElement();
            this.addChild(valuesElement);
        }
    }

    TFMListValueElement valueElement = new TFMListValueElement();
    valueElement.parmDataMemberValue(_dataMemberValue);
    valueElement.parmImageId(_ImageId);

    valuesElement.addChild(valueElement);

    return valueElement;
}

public static TFMListImageElement ConstructImageElement(TFMDataSetField _sourceId, TFMDataSetField _dataMember, int _width, int _height, TFMListXAlign _xAlign = SysChartHorizontalAlignment::Left, TFMListYAlign _yAlign = TFMVerticalAlignment::Top)
{
    TFMListImageElement imgElement = new TFMListImageElement();
    imgElement.parmSourceId(_sourceId);
    imgElement.parmDataMember(_dataMember);
    imgElement.parmwidth(_width);
    imgElement.parmheight(_height);
    imgElement.parmHorizontalAlignment(_xAlign);
    imgElement.parmVerticalAlignment(_yAlign);
    return imgElement;
}

protected System.Drawing.Image findImage(Map _valuesMap)
{
    str base64 = TFMDocGetMedia::getBase64FromName(this.replaceTextWithValue(sourceId, _valuesMap));
    System.Drawing.Image itemImage = TFMImageHelper::base64ToImage(base64 ? base64 : 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=');
    return itemImage;
}

public void appendToXML(XmlElement _parent, boolean _expandCustomComponents)
{
    XmlElement		imageElement =_parent.ownerDocument().createElement('imageElement');
    TFMListbase 	valueElement;
    MapEnumerator	mEnum;
    imageElement.setAttribute('sourceId',sourceId);
    if(horizontalAlignment != SysChartHorizontalAlignment::Auto)
    {
        imageElement.setAttribute('horizontalAlignment', strLwr(enum2Symbol(enumNum(SysChartHorizontalAlignment), horizontalAlignment)));
    }
    imageElement.setAttribute('verticalAlignment', strLwr(enum2Symbol(enumNum(TFMVerticalAlignment), verticalAlignment)));

    imageElement.setAttribute('width',int2Str(width));
    if (height)
    {
        imageElement.setAttribute('height',int2Str(height));
    }
    if (dataMember)
    {
        imageElement.setAttribute('dataMember',dataMember);
    }
    if (baseChildren && baseChildren.elements())
    {
        mEnum = baseChildren.getEnumerator();
        while(mEnum.moveNext())
        {
            valueElement = mEnum.currentValue();
            valueElement.appendToXML(imageElement, _expandCustomComponents);
        }
     }
    _parent.appendChild(imageElement);
}
